uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Base parameter mappings
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;

// Expanded control faders
uniform float u_strand_count;
uniform float u_core_glow;
uniform float u_halo_glow;
uniform float u_dust_amount;
uniform float u_distortion;
uniform float u_hue_shift;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// Cyberpunk Palette
vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.2, 0.8);
    vec3 b = vec3(0.4, 0.6, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.0, 0.33, 0.67);
    return a + b * cos(6.28318 * (c * t + d));
}

// Lemniscate of Bernoulli (Infinity Symbol) Exact Distance
float infinityKnot(vec2 p, float scale) {
    p *= scale;
    float r2 = dot(p, p);
    float a2 = 0.65; 
    float val = r2 * r2 - a2 * (p.x * p.x - p.y * p.y);
    vec2 grad = vec2(4.0 * r2 * p.x - 2.0 * a2 * p.x, 
                     4.0 * r2 * p.y + 2.0 * a2 * p.y);
    return abs(val) / max(length(grad), 0.0001);
}

// Fine Dust Pattern
float getDust(vec2 uv, float t) {
    float gridSize = 60.0; 
    vec2 id = floor(uv * gridSize);
    vec2 f = fract(uv * gridSize);

    float r = hash(id);
    vec2 pos = vec2(r, fract(r * 12.34));

    float d = distance(f, pos);
    float size = 0.04 * (0.5 + 0.5 * sin(t * 4.0 + r * 20.0));

    float spark = smoothstep(size, size * 0.4, d);
    return spark * r; 
}

void main() {
    // Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // Fader Safeties & Defaults (Fallback to 1.0/0.0 if sliders hit absolute 0)
    float spd = (u_speed <= 0.0) ? 0.3 : u_speed;
    float scale = (u_scale <= 0.0) ? 1.0 : u_scale;
    float brightness = (u_intensity <= 0.0) ? 1.5 : u_intensity;
    float density = (u_layers <= 0.0) ? 4.0 : u_layers;

    float strandFreq = 120.0 * ((u_strand_count <= 0.0) ? 1.0 : u_strand_count);
    float coreSharpness = 30.0 / ((u_core_glow <= 0.0) ? 1.0 : u_core_glow);
    float haloSize = 8.0 / ((u_halo_glow <= 0.0) ? 1.0 : u_halo_glow);
    float dustVal = (u_dust_amount <= 0.0) ? 1.0 : u_dust_amount;
    float distAmp = (u_distortion <= 0.0) ? 1.0 : u_distortion;

    float t = iTime * spd;
    float colorShift = u_hue_shift + t * u_color_cycle;

    // --- Background (Deep Cosmic Void) ---
    vec3 bgTop = vec3(0.05, 0.0, 0.15);
    vec3 bgBottom = vec3(0.0, 0.05, 0.1);
    vec3 finalColor = mix(bgBottom, bgTop, uv0.y + 0.5 + 0.1 * sin(t * 0.5));

    // --- Layer Loop ---
    for(float i = 0.0; i < 8.0; i++) { // Max 8 background neural layers
        if(i >= density) break;

        vec2 flowUV = uv0 * (1.5 + i * 0.2) * scale;
        flowUV *= rot(t * 0.15 - i * 0.5);

        // Domain warping with distortion fader control
        float wave = sin(flowUV.y * 3.0 + t * 2.0) * 0.3 * distAmp;
        wave += cos(flowUV.x * 2.0 - t + i) * 0.3 * distAmp;
        float lineDist = abs(flowUV.x + wave);

        float flowGlow = exp(-lineDist * 8.0) * 0.3;

        vec2 dustUV = flowUV + vec2(wave * 0.5, t * 0.1);
        float dust = getDust(dustUV + vec2(i * 4.0, i * 7.0), t) * exp(-lineDist * 1.5) * dustVal;

        vec3 flowCol = palette(length(uv0) + i * 0.4 + colorShift);

        finalColor += flowCol * flowGlow * brightness;
        finalColor += mix(flowCol, vec3(0.4, 1.0, 1.0), 0.8) * dust * brightness * 1.5;
    }

    // --- The Main Infinity Core ---
    float infDist = infinityKnot(uv0, 1.8 * scale);

    // Applying strand and glow faders
    float strands = smoothstep(0.0, 1.0, sin(infDist * strandFreq - t * 10.0) * 0.5 + 0.5);
    float tubeMask = smoothstep(0.08, 0.02, infDist);
    strands *= tubeMask;

    float infCore = exp(-infDist * coreSharpness); 
    float infHalo = exp(-infDist * haloSize) * 0.6;

    vec3 infCol = mix(vec3(0.0, 0.8, 1.0), vec3(1.0, 0.0, 0.8), sin(uv0.x * 3.0 + t + colorShift) * 0.5 + 0.5);
    infCol = mix(infCol, vec3(1.0, 1.0, 1.0), infCore * 0.8); // White hot center

    // Combine Infinity components
    finalColor += infCol * (strands * 2.0 + infCore * 1.5 + infHalo) * brightness;

    // --- Post-Processing ---
    float vig = smoothstep(1.5, 0.1, length(uv0));
    finalColor *= vig;

    // Tone Mapping
    finalColor = smoothstep(0.0, 1.2, finalColor);

    // Correct WebGL2 Output matching your template
    fragColor = vec4(finalColor, 1.0);
}
